const r = await tools.exec_command({cmd:"@'
import sys,csv,json,pathlib,re
sys.path.insert(0,'code')
from identity_resolution import resolve_subjects
from pypdf import PdfReader
from PIL import Image
root=pathlib.Path('dataset')
def csvrows(name):
    with (root/name).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
requests={r['case_id']:r for r in csvrows('sample_deletion_requests.csv')}
outputs={r['case_id']:r for r in csvrows('sample_output.csv')}
ids=csvrows('user_identities.csv'); audits=csvrows('user_audit_log.csv'); manifest=csvrows('evidence_files.csv')
manifest_by={r['file_id']:r for r in manifest}
resource_re=re.compile(r'\b(?:account|search|support|analytics|audit_record|tombstone|data_flow|backup|export|marketing|delivery|cache|telemetry)[_-][A-Za-z0-9_-]+\b',re.I)
for case_id in [f'case_{i:02}' for i in range(1,13)]:
    req=requests[case_id]
    subjects=resolve_subjects(req['email'],ids,audits,req['audit_at'])
    want=set();
    for s in subjects:
        want.update(s.identifiers)
    refs=[]
    for step in json.loads(outputs[case_id]['steps_json']):
        refs.append((step['system_id'],step['resource_id'],step['operation'],step['evidence_id']))
    print('\n',case_id,'subjects=',[s.user_id for s in subjects],'expected refs=',refs)
    hits=[]
    for ev in manifest:
        p=root/ev['file_path']; ext=p.suffix.lower()
        try:
            if ext=='.json': raw=p.read_text(encoding='utf-8',errors='replace')
            elif ext in ('.log','.txt','.sql'): raw=p.read_text(encoding='utf-8',errors='replace')
            elif ext=='.pdf': raw='\n'.join(pg.extract_text() or '' for pg in PdfReader(str(p)).pages)
            else: continue
        except Exception: continue
        lower=raw.casefold()
        if not any(v and v.casefold() in lower for v in want): continue
        res=sorted(set(resource_re.findall(raw)))
        hits.append((ev['file_id'],p.suffix.lower(),res[:15]))
    print('matched evidence=',hits[:15])
'@ | python -","workdir":"C:\Projects\hackerrank-orchestrate-october26-main\hackerrank-orchestrate-october26-main","yield_time_ms":10000,"max_output_tokens":6000}); text(r.output);

