"""Extract searchable evidence records from every manifest-backed format."""

from __future__ import annotations

import json
import re
import shlex
import sqlite3
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Mapping

from data_loading import Dataset


class EvidenceReadError(RuntimeError):
    """Raised when required evidence cannot be read safely."""


RESOURCE_PATTERN = re.compile(
    r"\b(?:account|search|support|analytics|audit_record|tombstone|data_flow|backup|export|"
    r"marketing|cache|telemetry|email_delivery|secondary_identifier|legal_hold|support_attachment)"
    r"[_-][A-Za-z0-9_-]+\b|\bORD-[A-Za-z0-9-]+\b|\bCS-[A-Za-z0-9-]+\b",
    re.IGNORECASE,
)

CATEGORY_ALIASES = {
    "USER_PROFILE": "USER_PROFILE",
    "SECONDARY_IDENTIFIER": "SECONDARY_IDENTIFIER",
    "SEARCH_INDEX_ENTRY": "SEARCH_INDEX_ENTRY",
    "CACHE_ENTRY": "CACHE_ENTRY",
    "SUPPORT_MESSAGE": "SUPPORT_MESSAGE",
    "SUPPORT_ATTACHMENT": "SUPPORT_ATTACHMENT",
    "ANALYTICS_PROFILE": "ANALYTICS_PROFILE",
    "PRODUCT_TELEMETRY": "PRODUCT_TELEMETRY",
    "USER_EXPORT": "USER_EXPORT",
    "MARKETING_PROFILE": "MARKETING_PROFILE",
    "EMAIL_DELIVERY_LOG": "EMAIL_DELIVERY_LOG",
    "SECURITY_AUDIT_LOG": "SECURITY_AUDIT_LOG",
    "LEGAL_HOLD_RECORD": "LEGAL_HOLD_RECORD",
    "BACKUP_ARCHIVE": "BACKUP_ARCHIVE",
    "ACCOUNT_TOMBSTONE": "ACCOUNT_TOMBSTONE",
    "DATA_FLOW": "DATA_FLOW",
}


@dataclass(frozen=True)
class EvidenceRecord:
    evidence_id: str
    available_at: str
    observed_at: str
    system_id: str
    resource_id: str
    data_category: str
    source_component: str
    file_path: str
    source_kind: str
    fields: Mapping[str, Any]
    text: str


@dataclass(frozen=True)
class EvidenceCoverage:
    """A point-in-time snapshot that covers a category/component."""

    evidence_id: str
    available_at: str
    observed_at: str
    system_id: str
    data_category: str
    source_component: str
    present_resource_ids: frozenset[str]
    file_path: str


@dataclass(frozen=True)
class EvidenceCorpus:
    records: tuple[EvidenceRecord, ...]
    coverage: tuple[EvidenceCoverage, ...]


def normalize_category(value: str, fallback: str = "") -> str:
    """Map source collection/table names to challenge policy categories."""
    candidate = value.strip().upper().replace("-", "_").replace(" ", "_")
    if candidate in CATEGORY_ALIASES:
        return CATEGORY_ALIASES[candidate]
    lowered = f"{candidate} {fallback.upper()}"
    if "TOMBSTONE" in lowered or "DELETED_CUSTOMER_REFERENCE" in lowered:
        return "ACCOUNT_TOMBSTONE"
    if "SECURITY" in lowered or "AUDIT_RECORD" in lowered or "AUDIT_EVENT" in lowered:
        return "SECURITY_AUDIT_LOG"
    if "LEGAL_HOLD" in lowered or "RETAINED_ORDER" in lowered:
        return "LEGAL_HOLD_RECORD"
    if "BACKUP" in lowered or "RESTORE" in lowered or "ARCHIVE" in lowered:
        return "BACKUP_ARCHIVE"
    if "CONNECTOR" in lowered or "DATA_FLOW" in lowered or "SUBSCRIPTION" in lowered:
        return "DATA_FLOW"
    if "SEARCH" in lowered or "INDEX" in lowered:
        return "SEARCH_INDEX_ENTRY"
    if "CACHE" in lowered:
        return "CACHE_ENTRY"
    if "ANALYTIC" in lowered:
        return "ANALYTICS_PROFILE"
    if "TELEMETRY" in lowered or "PRODUCT_EVENT" in lowered:
        return "PRODUCT_TELEMETRY"
    if "EXPORT" in lowered:
        return "USER_EXPORT"
    if "MARKETING" in lowered:
        return "MARKETING_PROFILE"
    if "DELIVERY" in lowered or "EMAIL_LOG" in lowered:
        return "EMAIL_DELIVERY_LOG"
    if "ATTACHMENT" in lowered:
        return "SUPPORT_ATTACHMENT"
    if "SUPPORT" in lowered or "TICKET" in lowered or "CONVERSATION" in lowered:
        return "SUPPORT_MESSAGE"
    if "PROFILE" in lowered or "ACCOUNT" in lowered:
        return "USER_PROFILE"
    if "SECONDARY_IDENTIFIER" in lowered:
        return "SECONDARY_IDENTIFIER"
    return ""


def infer_system(value: str, category: str = "", component: str = "") -> str:
    candidate = " ".join((value, component)).casefold()
    if "identity" in candidate or "tombstone" in candidate:
        return "identity_service"
    if "account" in candidate or category == "USER_PROFILE":
        return "account_service"
    if "search" in candidate or category == "SEARCH_INDEX_ENTRY":
        return "search_service"
    if "analytics" in candidate or category == "ANALYTICS_PROFILE":
        return "analytics_platform"
    if "support" in candidate or category in {"SUPPORT_MESSAGE", "SUPPORT_ATTACHMENT"}:
        return "support_platform"
    if "security" in candidate or category == "SECURITY_AUDIT_LOG":
        return "security_service"
    if "legal" in candidate or category == "LEGAL_HOLD_RECORD":
        return "legal_service"
    if "backup" in candidate or "restore" in candidate or category == "BACKUP_ARCHIVE":
        return "backup_service"
    if "connector" in candidate or "integration" in candidate or category == "DATA_FLOW":
        return "integration_service"
    if "export" in candidate or category == "USER_EXPORT":
        return "export_service"
    if "marketing" in candidate or category == "MARKETING_PROFILE":
        return "marketing_service"
    if "delivery" in candidate or category == "EMAIL_DELIVERY_LOG":
        return "email_delivery_service"
    if "cache" in candidate or category == "CACHE_ENTRY":
        return "cache_service"
    if "telemetry" in candidate or category == "PRODUCT_TELEMETRY":
        return "telemetry_service"
    return value.strip() or "unknown_system"


def _first_text(fields: Mapping[str, Any], keys: Iterable[str]) -> str:
    for key in keys:
        value = fields.get(key)
        if isinstance(value, (str, int, float)) and str(value).strip():
            return str(value).strip()
    return ""


def _flatten_text(value: Any) -> str:
    if isinstance(value, Mapping):
        return " ".join(f"{key} {_flatten_text(item)}" for key, item in value.items())
    if isinstance(value, (list, tuple, set)):
        return " ".join(_flatten_text(item) for item in value)
    return str(value) if value is not None else ""


def _resource_id(fields: Mapping[str, Any], text: str = "") -> str:
    value = _first_text(fields, ("resource_id", "_id", "record_id", "tombstone_id", "ticket_id", "archive_id", "export_id", "object_id"))
    if value:
        return value
    match = RESOURCE_PATTERN.search(text)
    return match.group(0) if match else ""


def _make_record(
    evidence_id: str,
    available_at: str,
    file_path: str,
    source_kind: str,
    fields: Mapping[str, Any],
    context: Mapping[str, str] | None = None,
    text: str = "",
    observed_at: str = "",
    resource_override: str = "",
) -> EvidenceRecord:
    context = context or {}
    combined = {**context, **fields}
    category_value = _first_text(combined, ("data_category", "record_type", "category", "collection", "table_name"))
    category = normalize_category(category_value, file_path)
    component = _first_text(combined, ("collection", "table_name", "source_component", "system")) or context.get("collection", "") or context.get("table", "")
    system_value = _first_text(combined, ("system_id", "system", "service", "service_id", "origin_system", "data_store", "source_system"))
    system_id = infer_system(system_value or context.get("service", "") or context.get("data_store", "") or context.get("origin", ""), category, component)
    timestamp = observed_at or _first_text(combined, ("observed_at", "recorded_at", "event_time", "captured_at", "updated_at", "indexed_at", "created_at", "exported_at")) or available_at
    rendered = text or _flatten_text(fields)
    return EvidenceRecord(
        evidence_id=evidence_id,
        available_at=available_at,
        observed_at=timestamp,
        system_id=system_id,
        resource_id=resource_override or _resource_id(fields, rendered),
        data_category=category,
        source_component=component or source_kind,
        file_path=file_path,
        source_kind=source_kind,
        fields=dict(fields),
        text=rendered,
    )


def _looks_like_record(value: Mapping[str, Any]) -> bool:
    return any(key in value for key in ("resource_id", "_id", "record_id", "tombstone_id", "ticket_id", "archive_id", "export_id", "object_id"))


def _read_json(evidence_id: str, available_at: str, file_path: str, path: Path) -> tuple[list[EvidenceRecord], list[EvidenceCoverage]]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise EvidenceReadError(f"Could not parse JSON evidence {file_path}: {exc}") from exc

    records: list[EvidenceRecord] = []
    coverage: list[EvidenceCoverage] = []

    def walk(value: Any, context: dict[str, str], parent_key: str = "") -> None:
        if isinstance(value, list):
            for item in value:
                walk(item, context, parent_key)
            return
        if not isinstance(value, Mapping):
            return

        current = dict(context)
        for key in ("source", "origin", "service", "system", "system_id", "origin_system", "data_store", "collection", "region"):
            field = value.get(key)
            if isinstance(field, str) and field.strip():
                current[key] = field.strip()
        if parent_key and parent_key not in {"records", "snapshots", "service_exports"} and "collection" not in current:
            current["collection"] = parent_key

        if "records" in value and isinstance(value["records"], list):
            category = normalize_category(current.get("collection", ""), file_path)
            system = infer_system(current.get("data_store", current.get("service", "")), category, current.get("collection", ""))
            observed = current.get("captured_at", current.get("exported_at", available_at))
            component = current.get("collection", "")
            ids: set[str] = set()
            for item in value["records"]:
                if isinstance(item, Mapping):
                    rid = _resource_id(item, _flatten_text(item))
                    if rid:
                        ids.add(rid)
                    walk(item, current, "records")
            if category:
                coverage.append(EvidenceCoverage(evidence_id, available_at, observed, system, category, component, frozenset(ids), file_path))

        if _looks_like_record(value):
            record_context = dict(current)
            if parent_key and parent_key not in {"records", "snapshots", "service_exports"}:
                record_context.setdefault("collection", parent_key)
            observed = _first_text(value, ("observed_at", "recorded_at", "event_time", "captured_at", "updated_at", "indexed_at", "created_at")) or current.get("captured_at", "")
            records.append(_make_record(evidence_id, available_at, file_path, "json", value, record_context, observed_at=observed))

        for key, child in value.items():
            if key == "records":
                continue
            if key == "service_exports" and isinstance(child, Mapping):
                for service, service_payload in child.items():
                    nested = dict(current)
                    nested["service"] = str(service)
                    walk(service_payload, nested, str(service))
            elif key == "snapshots" and isinstance(child, list):
                for snapshot in child:
                    if not isinstance(snapshot, Mapping):
                        continue
                    snap_context = dict(current)
                    snap_context.update({
                        "data_store": str(snapshot.get("data_store", "")),
                        "collection": str(snapshot.get("collection", "")),
                        "captured_at": str(snapshot.get("captured_at", available_at)),
                    })
                    walk(snapshot, snap_context, "snapshots")
            elif isinstance(child, (Mapping, list)):
                walk(child, current, str(key))

    initial = {key: str(payload[key]) for key in ("source", "origin", "exported_at", "captured_at") if isinstance(payload, Mapping) and isinstance(payload.get(key), str)}
    walk(payload, initial)
    return records, coverage


def _read_sql(evidence_id: str, available_at: str, file_path: str, path: Path) -> tuple[list[EvidenceRecord], list[EvidenceCoverage]]:
    try:
        sql = path.read_text(encoding="utf-8-sig", errors="replace")
        connection = sqlite3.connect(":memory:")
        connection.executescript(sql)
    except (OSError, sqlite3.Error) as exc:
        raise EvidenceReadError(f"Could not read SQL evidence {file_path}: {exc}") from exc

    header_match = re.search(r"Captured at:\s*(\S+)", sql, re.IGNORECASE)
    default_observed = header_match.group(1) if header_match else available_at
    records: list[EvidenceRecord] = []
    coverage: list[EvidenceCoverage] = []
    try:
        table_names = [row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")]
        for table in table_names:
            if table == "snapshot_scope":
                continue
            quoted = '"' + table.replace('"', '""') + '"'
            rows = [dict(row) for row in connection.execute(f"SELECT * FROM {quoted}").fetchall()]
            component_categories: dict[tuple[str, str], set[str]] = {}
            component_resources: dict[tuple[str, str], set[str]] = {}
            for row in rows:
                fields: dict[str, Any] = dict(row)
                if isinstance(fields.get("record_json"), str):
                    try:
                        nested = json.loads(fields["record_json"])
                    except json.JSONDecodeError:
                        nested = {}
                    if isinstance(nested, Mapping):
                        fields = {**fields, **nested}
                fallback = str(row.get("collection_name", table))
                category = normalize_category(_first_text(fields, ("data_category", "record_type", "category", "collection_name")), table + " " + fallback)
                if not category:
                    continue
                system_value = _first_text(fields, ("system_id", "system", "service", "origin_system", "source_system"))
                system_id = infer_system(system_value, category, table)
                component = f"{table}:{fallback}" if "collection_name" in row else table
                timestamp = _first_text(fields, ("observed_at", "recorded_at", "event_time", "captured_at", "updated_at", "indexed_at")) or default_observed
                rid = _resource_id(fields, _flatten_text(fields))
                if rid:
                    component_resources.setdefault((system_id, component), set()).add(rid)
                component_categories.setdefault((system_id, component), set()).add(category)
                records.append(_make_record(evidence_id, available_at, file_path, "sql", fields, {"table": table, "collection": fallback}, observed_at=timestamp, resource_override=rid))
            # Empty tables still provide point-in-time coverage for their category.
            if not rows:
                category = normalize_category(table, file_path)
                if category:
                    system_id = infer_system("", category, table)
                    component_categories.setdefault((system_id, table), set()).add(category)
            for (system_id, component), categories in component_categories.items():
                for category in categories:
                    coverage.append(EvidenceCoverage(
                        evidence_id, available_at, default_observed, system_id, category, component,
                        frozenset(component_resources.get((system_id, component), set())), file_path,
                    ))
    finally:
        connection.close()
    return records, coverage


def _parse_key_value_line(line: str) -> tuple[str, dict[str, Any]]:
    timestamp = line.split(maxsplit=1)[0] if line.strip() else ""
    body = line[len(timestamp):].strip() if timestamp else line.strip()
    fields: dict[str, Any] = {}
    if body.startswith("{"):
        try:
            parsed = json.loads(body)
            if isinstance(parsed, Mapping):
                fields = dict(parsed)
        except json.JSONDecodeError:
            pass
    if not fields:
        try:
            tokens = shlex.split(body, posix=True)
        except ValueError:
            tokens = body.split()
        for token in tokens:
            if "=" not in token:
                continue
            key, value = token.split("=", 1)
            fields[key] = value.strip('"\\')
    fields.setdefault("event_time", timestamp)
    fields.setdefault("message", body)
    return timestamp, fields


def _read_log(evidence_id: str, available_at: str, file_path: str, path: Path) -> list[EvidenceRecord]:
    try:
        lines = path.read_text(encoding="utf-8-sig", errors="replace").splitlines()
    except OSError as exc:
        raise EvidenceReadError(f"Could not read log evidence {file_path}: {exc}") from exc
    records: list[EvidenceRecord] = []
    for line in lines:
        if not line.strip():
            continue
        observed, fields = _parse_key_value_line(line)
        rid = _resource_id(fields, line)
        category = normalize_category(_first_text(fields, ("data_category", "record_type", "category", "collection")), line)
        if not category:
            category = normalize_category("", rid)
        if rid or category:
            records.append(_make_record(evidence_id, available_at, file_path, "log", fields, {"collection": category}, text=line, observed_at=observed, resource_override=rid))
    return records


def _read_text(evidence_id: str, available_at: str, file_path: str, path: Path) -> list[EvidenceRecord]:
    try:
        text = path.read_text(encoding="utf-8-sig", errors="replace")
    except OSError as exc:
        raise EvidenceReadError(f"Could not read text evidence {file_path}: {exc}") from exc
    records: list[EvidenceRecord] = []
    for line in text.splitlines():
        stripped = line.strip().lstrip("- ")
        parts = [part.strip() for part in stripped.split("|")]
        if len(parts) >= 6:
            fields = {
                "event_time": parts[0], "system": parts[1], "resource_id": parts[2],
                "record_type": parts[3], "result": parts[4], "subject_reference": parts[5],
            }
            records.append(_make_record(evidence_id, available_at, file_path, "text", fields, text=line, observed_at=parts[0]))
    if not records:
        for resource_id in sorted(set(RESOURCE_PATTERN.findall(text))):
            records.append(_make_record(evidence_id, available_at, file_path, "text", {"resource_id": resource_id, "text": text}, text=text, resource_override=resource_id))
    return records


def _read_pdf(evidence_id: str, available_at: str, file_path: str, path: Path) -> list[EvidenceRecord]:
    try:
        from pypdf import PdfReader
    except ImportError as exc:
        raise EvidenceReadError("PDF reading requires pypdf; install the packages in requirements.txt") from exc
    try:
        reader = PdfReader(str(path))
    except Exception as exc:
        raise EvidenceReadError(f"Could not open PDF evidence {file_path}: {exc}") from exc
    records: list[EvidenceRecord] = []
    for page_number, page in enumerate(reader.pages, start=1):
        text = page.extract_text() or ""
        if not text.strip():
            continue
        lines = text.splitlines()
        resource_ids = sorted(set(RESOURCE_PATTERN.findall(text)))
        if resource_ids:
            for resource_id in resource_ids:
                index = next((i for i, line in enumerate(lines) if resource_id.casefold() in line.casefold()), 0)
                excerpt = " ".join(lines[max(0, index - 2):index + 4])
                records.append(_make_record(evidence_id, available_at, file_path, "pdf", {"resource_id": resource_id, "page": page_number, "text": excerpt}, text=excerpt, resource_override=resource_id))
        else:
            records.append(_make_record(evidence_id, available_at, file_path, "pdf", {"page": page_number, "text": text}, text=text))
    return records


def _image_category(file_path: str, text: str) -> str:
    lowered = (file_path + " " + text).casefold()
    for marker, category in (
        ("security_audit", "SECURITY_AUDIT_LOG"),
        ("backup", "BACKUP_ARCHIVE"),
        ("connector", "DATA_FLOW"),
        ("search_index", "SEARCH_INDEX_ENTRY"),
        ("analytics", "ANALYTICS_PROFILE"),
        ("marketing", "MARKETING_PROFILE"),
        ("customer_export", "USER_EXPORT"),
        ("object_storage", "SUPPORT_ATTACHMENT"),
        ("support_ticket", "SUPPORT_MESSAGE"),
        ("deleted_account", "ACCOUNT_TOMBSTONE"),
        ("account_admin", "USER_PROFILE"),
    ):
        if marker in lowered:
            return category
    return normalize_category("", lowered)


def _read_image(evidence_id: str, available_at: str, file_path: str, path: Path) -> list[EvidenceRecord]:
    try:
        from PIL import Image
        import pytesseract
    except ImportError as exc:
        raise EvidenceReadError("Screenshot reading requires Pillow and pytesseract; install requirements.txt and Tesseract OCR") from exc
    try:
        with Image.open(path) as image:
            text = pytesseract.image_to_string(image)
    except Exception as exc:
        raise EvidenceReadError(f"Could not OCR image evidence {file_path}: {exc}") from exc
    lines = text.splitlines()
    records: list[EvidenceRecord] = []
    category = _image_category(file_path, text)
    for resource_id in sorted(set(RESOURCE_PATTERN.findall(text))):
        index = next((i for i, line in enumerate(lines) if resource_id.casefold() in line.casefold()), 0)
        excerpt = " ".join(lines[max(0, index - 2):index + 4])
        fields = {"resource_id": resource_id, "record_type": category, "text": excerpt}
        records.append(_make_record(evidence_id, available_at, file_path, "image", fields, text=excerpt, resource_override=resource_id))
    return records


def load_evidence(dataset: Dataset) -> EvidenceCorpus:
    """Parse every file listed by the participant-facing evidence manifest."""
    all_records: list[EvidenceRecord] = []
    all_coverage: list[EvidenceCoverage] = []
    for evidence_id, entry in sorted(dataset.evidence_manifest.items()):
        relative_path = entry["file_path"]
        path = dataset.evidence_path(evidence_id)
        extension = Path(relative_path).suffix.casefold()
        if extension == ".json":
            records, coverage = _read_json(evidence_id, entry["captured_at"], relative_path, path)
            all_records.extend(records)
            all_coverage.extend(coverage)
        elif extension == ".sql":
            records, coverage = _read_sql(evidence_id, entry["captured_at"], relative_path, path)
            all_records.extend(records)
            all_coverage.extend(coverage)
        elif extension == ".log":
            all_records.extend(_read_log(evidence_id, entry["captured_at"], relative_path, path))
        elif extension == ".txt":
            all_records.extend(_read_text(evidence_id, entry["captured_at"], relative_path, path))
        elif extension == ".pdf":
            all_records.extend(_read_pdf(evidence_id, entry["captured_at"], relative_path, path))
        elif extension == ".png":
            all_records.extend(_read_image(evidence_id, entry["captured_at"], relative_path, path))
        else:
            raise EvidenceReadError(f"Unsupported evidence type for {relative_path}")
    return EvidenceCorpus(tuple(all_records), tuple(all_coverage))

"""Build a case-scoped, cutoff-aware view over evidence and activity."""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Iterable, Mapping

from evidence import EvidenceCorpus, EvidenceCoverage, EvidenceRecord
from identity_resolution import ResolvedSubject


RESOURCE_REFERENCE_FIELDS = {
    "resource_id", "source_resource_id", "parent_resource_id", "customer_reference",
    "subject_reference", "account_reference", "archive_key", "object_key", "order_reference",
}


@dataclass(frozen=True)
class CaseTimeline:
    subject: ResolvedSubject
    audit_at: str
    evidence_records: tuple[EvidenceRecord, ...]
    coverage: tuple[EvidenceCoverage, ...]
    activity_events: tuple[Mapping[str, str], ...]
    resource_ids: frozenset[str]


def parse_timestamp(value: str) -> datetime | None:
    if not value:
        return None
    try:
        timestamp = datetime.fromisoformat(value.strip().replace("Z", "+00:00"))
    except ValueError:
        return None
    if timestamp.tzinfo is None:
        return timestamp.replace(tzinfo=timezone.utc)
    return timestamp.astimezone(timezone.utc)


def timestamp_is_at_or_before(value: str, cutoff: str) -> bool:
    timestamp = parse_timestamp(value)
    cutoff_time = parse_timestamp(cutoff)
    return timestamp is not None and cutoff_time is not None and timestamp <= cutoff_time


def _ascii_fold(value: str) -> str:
    folded = unicodedata.normalize("NFKD", value.casefold())
    return "".join(char for char in folded if not unicodedata.combining(char))


def _contains_identifier(text: str, identifier: str) -> bool:
    candidate = identifier.strip()
    if not candidate:
        return False
    folded_text = _ascii_fold(text)
    folded_candidate = _ascii_fold(candidate)
    if "@" in candidate:
        return candidate.casefold() in text.casefold()
    digits = re.sub(r"\D", "", candidate)
    if len(digits) >= 7 and len(digits) > len(candidate) // 2:
        return digits in re.sub(r"\D", "", text)
    if any(char.isspace() for char in candidate):
        return " ".join(folded_candidate.split()) in " ".join(folded_text.split())
    return re.search(rf"(?<![\w]){re.escape(folded_candidate)}(?![\w])", folded_text, re.IGNORECASE) is not None


def _subject_matches(record: EvidenceRecord, subject: ResolvedSubject) -> bool:
    searchable = record.text
    for identifier in subject.identifiers:
        if _contains_identifier(searchable, identifier):
            return True
    return False


def _extract_resource_references(record: EvidenceRecord) -> set[str]:
    found: set[str] = set()
    for key, value in record.fields.items():
        if key.casefold() not in RESOURCE_REFERENCE_FIELDS:
            continue
        if isinstance(value, str) and value.strip():
            found.add(value.strip())
    return found


def build_case_timeline(
    corpus: EvidenceCorpus,
    subject: ResolvedSubject,
    audit_at: str,
    system_activity: Iterable[Mapping[str, str]],
) -> CaseTimeline:
    """Connect subject records, related resource IDs, and events up to cutoff."""
    if parse_timestamp(audit_at) is None:
        raise ValueError(f"Invalid audit_at timestamp: {audit_at}")

    eligible_records = tuple(
        record for record in corpus.records
        if timestamp_is_at_or_before(record.available_at, audit_at)
        and timestamp_is_at_or_before(record.observed_at, audit_at)
    )
    eligible_coverage = tuple(
        item for item in corpus.coverage
        if timestamp_is_at_or_before(item.available_at, audit_at)
        and timestamp_is_at_or_before(item.observed_at, audit_at)
    )

    selected: set[int] = set()
    resource_ids = set(subject.linked_resource_ids)
    for index, record in enumerate(eligible_records):
        if _subject_matches(record, subject):
            selected.add(index)
            if record.resource_id:
                resource_ids.add(record.resource_id)
            resource_ids.update(_extract_resource_references(record))

    # Follow explicit resource references only; do not expand arbitrary text
    # mentions into unrelated records.
    changed = True
    while changed:
        changed = False
        for index, record in enumerate(eligible_records):
            if index in selected:
                continue
            if record.resource_id and record.resource_id in resource_ids:
                selected.add(index)
                resource_ids.update(_extract_resource_references(record))
                changed = True
                continue
            references = _extract_resource_references(record)
            if references.intersection(resource_ids):
                selected.add(index)
                if record.resource_id:
                    resource_ids.add(record.resource_id)
                resource_ids.update(references)
                changed = True

    relevant_records = tuple(sorted(
        (eligible_records[index] for index in selected),
        key=lambda record: (record.observed_at, record.evidence_id, record.system_id, record.resource_id),
    ))
    relevant_coverage = tuple(
        item for item in eligible_coverage
        if item.present_resource_ids.intersection(resource_ids)
        or any(record.system_id == item.system_id and record.data_category == item.data_category for record in relevant_records)
    )

    relevant_activities: list[Mapping[str, str]] = []
    for event in system_activity:
        if not timestamp_is_at_or_before(event.get("event_time", ""), audit_at):
            continue
        if event.get("resource_id", "") in resource_ids or _subject_matches_text(event.get("details", ""), subject):
            relevant_activities.append(event)

    return CaseTimeline(
        subject=subject,
        audit_at=audit_at,
        evidence_records=relevant_records,
        coverage=relevant_coverage,
        activity_events=tuple(sorted(relevant_activities, key=lambda event: (event.get("event_time", ""), event.get("activity_id", "")))),
        resource_ids=frozenset(resource_ids),
    )


def _subject_matches_text(text: str, subject: ResolvedSubject) -> bool:
    return any(_contains_identifier(text, identifier) for identifier in subject.identifiers)

"""Policy rule loading, state assessment, and required-treatment mapping."""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Iterable, Mapping

from evidence import EvidenceCoverage, EvidenceRecord
from identity_resolution import ResolvedSubject
from timeline import CaseTimeline, parse_timestamp


@dataclass(frozen=True)
class DeletionRule:
    rule_id: str
    data_category: str
    condition: str
    required_action: str


@dataclass(frozen=True)
class PolicyAssessment:
    system_id: str
    resource_id: str
    data_category: str
    action: str
    state: str
    evidence_id: str
    observed_at: str
    violation_operation: str = ""
    remediation_operation: str = ""
    remediation_state: str = ""
    verification_operation: str = ""
    verification_state: str = ""
    compliant: bool = True


def rules_from_rows(rows: Iterable[Mapping[str, str]]) -> tuple[DeletionRule, ...]:
    """Convert CSV rows into typed policy rules."""
    return tuple(
        DeletionRule(
            rule_id=row["rule_id"],
            data_category=row["data_category"],
            condition=row["condition"],
            required_action=row["required_action"].strip().upper(),
        )
        for row in rows
    )


def rules_for_category(category: str, rules: Iterable[DeletionRule]) -> tuple[DeletionRule, ...]:
    wanted = category.strip().casefold()
    return tuple(rule for rule in rules if rule.data_category.strip().casefold() == wanted)


def parse_bool(value: Any) -> bool | None:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        normalized = value.strip().casefold()
        if normalized in {"true", "yes", "1", "enabled", "active", "allowed", "open"}:
            return True
        if normalized in {"false", "no", "0", "disabled", "inactive", "blocked", "denied", "closed"}:
            return False
    return None


def _normalized_state(record: EvidenceRecord) -> str:
    fields = record.fields
    for key in ("result", "state", "status", "record_status", "deletion_status", "restore_status"):
        value = fields.get(key)
        if value is None:
            continue
        text = str(value).strip().upper().replace("-", "_").replace(" ", "_")
        if text in {"NOT_FOUND", "ABSENT", "DELETED", "REMOVED", "PURGED", "404", "MISSING"}:
            return "ABSENT"
        if text in {"ANONYMIZED", "ANONYMISED"}:
            return "ANONYMIZED"
        if text in {"REDACTED", "MASKED"}:
            return "REDACTED"
        if text in {"BLOCKED", "RESTORE_BLOCKED"}:
            return "BLOCKED"
        if text in {"DISABLED", "INACTIVE", "STOPPED"}:
            return "DISABLED"
        if text in {"ACTIVE", "ENABLED", "IDENTIFIABLE", "FOUND", "PRESENT", "READY", "AVAILABLE", "SUCCESS", "200"}:
            return "PRESENT"

    for key in ("status_code", "http_status", "response_code"):
        value = fields.get(key)
        try:
            code = int(value)
        except (TypeError, ValueError):
            continue
        if code >= 400:
            return "ABSENT"

    for key in ("exists", "record_exists", "present", "found", "download_available"):
        value = parse_bool(fields.get(key))
        if value is False:
            return "ABSENT"
    if parse_bool(fields.get("deleted")) is True:
        return "ABSENT"

    if record.data_category == "DATA_FLOW":
        enabled = parse_bool(fields.get("enabled", fields.get("active")))
        if enabled is True:
            return "ACTIVE"
        if enabled is False:
            return "DISABLED"
    if record.data_category == "BACKUP_ARCHIVE":
        allowed = parse_bool(fields.get("restore_allowed", fields.get("restore_enabled")))
        if allowed is True:
            return "ACTIVE"
        if allowed is False:
            return "BLOCKED"
    return "PRESENT"


def _contains_identifier(text: str, identifier: str) -> bool:
    value = identifier.strip()
    if not value:
        return False
    if "@" in value or len(value) >= 16 and value.isalnum():
        return value.casefold() in text.casefold()
    if any(char.isspace() for char in value):
        return " ".join(value.casefold().split()) in " ".join(text.casefold().split())
    return re.search(rf"(?<![\w]){re.escape(value)}(?![\w])", text, re.IGNORECASE) is not None


def _has_direct_identifier(record: EvidenceRecord, subject: ResolvedSubject) -> bool:
    direct_fields = {
        "name", "full_name", "display_name", "email", "owner_email", "customer_email",
        "requester_email", "phone", "owner_phone", "requester_phone", "email_hash",
        "subject_reference", "customer_reference", "user_id", "user_reference",
        "message", "message_text", "message_excerpt", "document", "profile", "record_json",
    }
    if record.data_category == "ACCOUNT_TOMBSTONE":
        direct_fields -= {"user_id", "user_reference", "customer_reference"}

    needles = tuple(subject.identifiers)

    def visit(value: Any, parent_key: str = "") -> bool:
        if isinstance(value, Mapping):
            return any(visit(child, str(key).casefold()) for key, child in value.items())
        if isinstance(value, (list, tuple)):
            return any(visit(child, parent_key) for child in value)
        if not isinstance(value, str) or not value.strip():
            return False
        if parent_key and parent_key not in direct_fields and parent_key not in {"text", "details"}:
            return False
        return any(_contains_identifier(value, needle) for needle in needles)

    return visit(record.fields)


def _time(value: str) -> datetime:
    parsed = parse_timestamp(value)
    return parsed or datetime.min.replace(tzinfo=timezone.utc)


def _latest_by_component(
    records: Iterable[EvidenceRecord],
    coverage: Iterable[EvidenceCoverage],
    system_id: str,
    resource_id: str,
    category: str,
) -> tuple[list[tuple[EvidenceRecord | EvidenceCoverage, str]], bool]:
    grouped: dict[str, list[EvidenceRecord]] = {}
    for record in records:
        if (record.system_id, record.resource_id, record.data_category) != (system_id, resource_id, category):
            continue
        grouped.setdefault(record.source_component or record.source_kind, []).append(record)

    coverage_by_component: dict[str, list[EvidenceCoverage]] = {}
    for item in coverage:
        if (item.system_id, item.data_category) != (system_id, category):
            continue
        coverage_by_component.setdefault(item.source_component, []).append(item)

    latest: list[tuple[EvidenceRecord | EvidenceCoverage, str]] = []
    for component, component_records in grouped.items():
        current_record = max(component_records, key=lambda record: (_time(record.observed_at), _time(record.available_at)))
        component_coverage = coverage_by_component.get(component, [])
        if not component_coverage:
            # JSON/SQL readers may encode table names in the component while
            # a query result uses only a source label; only exact scopes apply.
            latest.append((current_record, _normalized_state(current_record)))
            continue
        current_scope = max(component_coverage, key=lambda item: (_time(item.observed_at), _time(item.available_at)))
        if _time(current_scope.observed_at) >= _time(current_record.observed_at) and resource_id not in current_scope.present_resource_ids:
            latest.append((current_scope, "ABSENT"))
        else:
            latest.append((current_record, _normalized_state(current_record)))

    # A full snapshot can establish absence even if no row survives in that
    # component; callers supply only resource IDs previously linked to subject.
    for component, component_scopes in coverage_by_component.items():
        if component in grouped:
            continue
        current_scope = max(component_scopes, key=lambda item: (_time(item.observed_at), _time(item.available_at)))
        if resource_id not in current_scope.present_resource_ids:
            latest.append((current_scope, "ABSENT"))

    return latest, bool(grouped or any(item.system_id == system_id and item.data_category == category for item in coverage))


def _is_retention_active(record: EvidenceRecord, audit_at: str) -> bool:
    retention_until = str(record.fields.get("retention_until", record.fields.get("retained_until", "")))
    if not retention_until:
        return True
    expiry = parse_timestamp(retention_until)
    cutoff = parse_timestamp(audit_at)
    return bool(expiry and cutoff and expiry >= cutoff)


def _rule_action(category: str, record: EvidenceRecord, rules: tuple[DeletionRule, ...], audit_at: str) -> str:
    matching = rules_for_category(category, rules)
    action = matching[0].required_action if matching else ""
    fields = record.fields
    if category == "DATA_FLOW":
        return "DISABLE_DATA_FLOW"
    if category == "BACKUP_ARCHIVE":
        can_block = parse_bool(fields.get("can_block_restore", fields.get("restore_access_blockable")))
        return "RETAIN" if can_block is not False else "DELETE"
    if category == "SECURITY_AUDIT_LOG" and not _is_retention_active(record, audit_at):
        return "DELETE"
    if category == "LEGAL_HOLD_RECORD":
        active = parse_bool(fields.get("active", fields.get("hold_active", fields.get("legal_hold_active"))))
        if active is False:
            return "DELETE"
    if category == "SUPPORT_ATTACHMENT":
        shared = parse_bool(fields.get("shared_context", fields.get("shared_with_others")))
        if shared is True:
            return "REDACT"
    return action


def assess_timeline(timeline: CaseTimeline, rules: Iterable[DeletionRule]) -> tuple[PolicyAssessment, ...]:
    """Apply policy to the latest evidence state of each linked resource."""
    rule_set = tuple(rules)
    resource_keys = sorted({
        (record.system_id, record.resource_id, record.data_category)
        for record in timeline.evidence_records
        if record.resource_id and record.data_category
    })
    resource_keys.extend(
        (item.system_id, resource_id, item.data_category)
        for item in timeline.coverage
        for resource_id in timeline.resource_ids
        if item.data_category and resource_id not in {""}
        and any(record.system_id == item.system_id and record.data_category == item.data_category for record in timeline.evidence_records)
    )
    resource_keys = sorted(set(resource_keys))

    assessments: list[PolicyAssessment] = []
    for system_id, resource_id, category in resource_keys:
        observations, known_scope = _latest_by_component(
            timeline.evidence_records, timeline.coverage, system_id, resource_id, category,
        )
        if not observations:
            continue
        action_record = max(
            (item for item, _ in observations),
            key=lambda item: (_time(item.observed_at), _time(item.available_at)),
        )
        if not isinstance(action_record, EvidenceRecord):
            continue
        action = _rule_action(category, action_record, rule_set, timeline.audit_at)
        if not action:
            continue

        present = [(item, state) for item, state in observations if state not in {"ABSENT"}]
        absent = not present
        violation_item: EvidenceRecord | EvidenceCoverage | None = None
        violation_operation = ""
        remediation_operation = ""
        remediation_state = ""
        verification_operation = ""
        verification_state = ""
        compliant = True
        state = "ABSENT" if absent else "PRESENT"

        if action == "DELETE":
            verification_operation, verification_state = "VERIFY_RECORD_ABSENT", "ABSENT"
            if not absent:
                violation_item = max((item for item, _ in present), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
                violation_operation = "REPORT_REMAINING_RECORD"
                remediation_operation, remediation_state = "DELETE_RECORD", "ABSENT"
                compliant, state = False, "PRESENT"
            else:
                item = max((item for item, _ in observations), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
                violation_item = item
        elif action == "REDACT":
            verification_operation, verification_state = "VERIFY_RECORD_REDACTED", "REDACTED"
            exposed = [item for item, _ in present if isinstance(item, EvidenceRecord) and _has_direct_identifier(item, timeline.subject)]
            if exposed:
                violation_item = max(exposed, key=lambda item: (_time(item.observed_at), _time(item.available_at)))
                violation_operation = "REPORT_EXPOSED_PII"
                remediation_operation, remediation_state = "REDACT_RECORD", "REDACTED"
                compliant, state = False, "PRESENT"
            elif present:
                state = "REDACTED"
                violation_item = max((item for item, _ in present), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
            else:
                state = "ABSENT"
                violation_item = max((item for item, _ in observations), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
        elif action == "ANONYMIZE":
            verification_operation, verification_state = "VERIFY_RECORD_ANONYMIZED", "ANONYMIZED"
            attributable = [item for item, _ in present if isinstance(item, EvidenceRecord) and _has_direct_identifier(item, timeline.subject)]
            if attributable:
                violation_item = max(attributable, key=lambda item: (_time(item.observed_at), _time(item.available_at)))
                violation_operation = "REPORT_EXPOSED_PII"
                remediation_operation, remediation_state = "ANONYMIZE_RECORD", "ANONYMIZED"
                compliant, state = False, "PRESENT"
            elif present:
                state = "ANONYMIZED"
                violation_item = max((item for item, _ in present), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
            else:
                # Missing analytics/telemetry is not a policy violation; this
                # operation permits de-identification but does not require retention.
                state = "ANONYMIZED"
                violation_item = max((item for item, _ in observations), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
        elif action == "RETAIN":
            verification_operation, verification_state = "VERIFY_RECORD_PRESENT", "PRESENT"
            if present:
                state = "PRESENT"
                violation_item = max((item for item, _ in present), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
            else:
                # The allowed output vocabulary has no finding for a missing
                # policy-required retained record; keep it out of the plan.
                continue
        elif action == "DISABLE_DATA_FLOW":
            verification_operation, verification_state = "VERIFY_DATA_FLOW_DISABLED", "DISABLED"
            active = [(item, item_state) for item, item_state in present if item_state == "ACTIVE"]
            if active:
                violation_item = max((item for item, _ in active), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
                violation_operation = "REPORT_ACTIVE_DATA_FLOW"
                remediation_operation, remediation_state = "DISABLE_DATA_FLOW", "DISABLED"
                compliant, state = False, "ACTIVE"
            else:
                violation_item = max((item for item, _ in observations), key=lambda item: (_time(item.observed_at), _time(item.available_at)))
                state = "DISABLED"
        else:
            continue

        if violation_item is None:
            continue
        assessments.append(PolicyAssessment(
            system_id=system_id,
            resource_id=resource_id,
            data_category=category,
            action=action,
            state=state,
            evidence_id=violation_item.evidence_id,
            observed_at=violation_item.observed_at,
            violation_operation=violation_operation,
            remediation_operation=remediation_operation,
            remediation_state=remediation_state,
            verification_operation=verification_operation,
            verification_state=verification_state,
            compliant=compliant,
        ))

    # A backup archive is retained by policy; only a live restore path is a risk.
    # Its restore_allowed flag is independent of the archive's own presence.
    backup_keys = [
        (record.system_id, record.resource_id, record.data_category)
        for record in timeline.evidence_records
        if record.resource_id and record.data_category == "BACKUP_ARCHIVE"
    ]
    for system_id, resource_id, category in sorted(set(backup_keys)):
        records = [record for record in timeline.evidence_records if (record.system_id, record.resource_id, record.data_category) == (system_id, resource_id, category)]
        latest = max(records, key=lambda record: (_time(record.observed_at), _time(record.available_at)))
        allowed = parse_bool(latest.fields.get("restore_allowed", latest.fields.get("restore_enabled")))
        result = str(latest.fields.get("result", latest.fields.get("status", ""))).upper()
        if allowed is True or result in {"ACTIVE", "RESTORE_ALLOWED", "RESTORABLE"}:
            assessments.append(PolicyAssessment(
                system_id=system_id,
                resource_id=resource_id,
                data_category=category,
                action="BLOCK_RESTORE",
                state="ACTIVE",
                evidence_id=latest.evidence_id,
                observed_at=latest.observed_at,
                violation_operation="REPORT_RESTORE_RISK",
                remediation_operation="BLOCK_RESTORE",
                remediation_state="BLOCKED",
                verification_operation="VERIFY_RESTORE_BLOCKED",
                verification_state="BLOCKED",
                compliant=False,
            ))
        elif allowed is False or result in {"BLOCKED", "RESTORE_BLOCKED"}:
            assessments.append(PolicyAssessment(
                system_id=system_id,
                resource_id=resource_id,
                data_category=category,
                action="BLOCK_RESTORE",
                state="BLOCKED",
                evidence_id=latest.evidence_id,
                observed_at=latest.observed_at,
                verification_operation="VERIFY_RESTORE_BLOCKED",
                verification_state="BLOCKED",
                compliant=True,
            ))

    # Keep only the latest assessment per system/resource/category/action.
    by_key: dict[tuple[str, str, str, str], PolicyAssessment] = {}
    for assessment in assessments:
        key = (assessment.system_id, assessment.resource_id, assessment.data_category, assessment.action)
        prior = by_key.get(key)
        if prior is None or _time(assessment.observed_at) >= _time(prior.observed_at):
            by_key[key] = assessment
    return tuple(sorted(by_key.values(), key=lambda item: (item.system_id, item.resource_id, item.action)))

"""Deletion intent, evidence timeline, policy assessment, and case steps."""

from __future__ import annotations

import re
import unicodedata
from typing import Mapping

from data_loading import Dataset
from evidence import EvidenceCorpus
from identity_resolution import ResolvedSubject, resolve_subjects
from output_generation import CasePrediction, Step
from policies import PolicyAssessment, assess_timeline, rules_from_rows
from timeline import CaseTimeline, build_case_timeline


_DELETION_PATTERNS = (
    re.compile(r"\b(delete|deletion|erase|erasure|destroy|purge)\b", re.IGNORECASE),
    re.compile(r"\b(close|remove)\s+(?:my|this|the|associated)\s+account\b", re.IGNORECASE),
    re.compile(r"\b(remove|erase|delete)\b.{0,80}\b(account|personal (?:data|information))\b", re.IGNORECASE),
    re.compile(r"\baccount[- ]deletion\b", re.IGNORECASE),
)
_NON_DELETION_PATTERNS = (
    re.compile(r"\bmarketing (?:lists?|emails?) only\b", re.IGNORECASE),
    re.compile(r"\b(?:stop|unsubscribe|opt[ -]?out)\b.{0,50}\b(?:promotional|marketing|emails?)\b", re.IGNORECASE),
    re.compile(r"\b(?:download|export|copy of|access|tell me what|information do you hold)\b", re.IGNORECASE),
    re.compile(r"\b(?:change|correct|correction|update|misspelled|out of date|reset(?:ting)?)\b", re.IGNORECASE),
    re.compile(r"\b(?:invoice|invoices|billing statement)\b", re.IGNORECASE),
    re.compile(r"\b(?:do not|don't|never)\s+(?:delete|erase|remove)\b", re.IGNORECASE),
)


def _fold_latin(text: str) -> str:
    normalized = unicodedata.normalize("NFKD", text.casefold())
    return "".join(char for char in normalized if not unicodedata.combining(char))


def request_authorizes_deletion(request_text: str) -> bool:
    """Detect explicit deletion intent, including supplied languages.

    The dataset includes English, Portuguese, Spanish, French, Japanese, and
    Korean requests. Non-deletion requests are checked first so marketing-only
    removal, access, correction, and export requests remain non-destructive.
    """
    text = request_text.strip()
    if not text:
        return False
    latin = _fold_latin(text)
    if any(pattern.search(latin) for pattern in _NON_DELETION_PATTERNS):
        return False
    if any(pattern.search(latin) for pattern in _DELETION_PATTERNS):
        return True
    # Portuguese, Spanish, and French terms after accent folding.
    if re.search(r"\b(exclusao|eliminacion|supression|suppression)\b", latin):
        return True
    # Japanese and Korean terms used by the supplied request templates.
    return "削除" in text or "삭제" in text


def _resolve_case_subject(request: Mapping[str, str], dataset: Dataset) -> ResolvedSubject:
    subjects = resolve_subjects(
        request.get("email", ""),
        dataset.identities,
        dataset.identity_audit_log,
        request.get("audit_at", ""),
        dataset.system_activity,
    )
    if not subjects:
        # Keep the supplied request identifier searchable if it is not present
        # in the current snapshot or audit history.
        email = request.get("email", "").strip()
        return ResolvedSubject(user_id="", identifiers=frozenset({email}) if email else frozenset())
    if len(subjects) == 1:
        return subjects[0]
    return ResolvedSubject(
        user_id="",
        identifiers=frozenset().union(*(subject.identifiers for subject in subjects)),
        linked_resource_ids=frozenset().union(*(subject.linked_resource_ids for subject in subjects)),
    )


def _step_from_assessment(assessment: PolicyAssessment, phase: str) -> Step | None:
    if phase == "FINDING":
        if not assessment.violation_operation:
            return None
        state = "ACTIVE" if assessment.violation_operation in {"REPORT_ACTIVE_DATA_FLOW", "REPORT_RESTORE_RISK"} else "PRESENT"
        return Step(
            phase="FINDING",
            system_id=assessment.system_id,
            resource_id=assessment.resource_id,
            operation=assessment.violation_operation,
            state=state,
            evidence_id=assessment.evidence_id,
        )
    if phase == "REMEDIATION":
        if not assessment.remediation_operation:
            return None
        return Step(
            phase="REMEDIATION",
            system_id=assessment.system_id,
            resource_id=assessment.resource_id,
            operation=assessment.remediation_operation,
            state=assessment.remediation_state,
        )
    if not assessment.verification_operation:
        return None
    return Step(
        phase="VERIFICATION",
        system_id=assessment.system_id,
        resource_id=assessment.resource_id,
        operation=assessment.verification_operation,
        state=assessment.verification_state,
        evidence_id=assessment.evidence_id if assessment.compliant else "",
    )


_OPERATION_ORDER = {
    "REPORT_REMAINING_RECORD": 0,
    "REPORT_EXPOSED_PII": 1,
    "REPORT_ACTIVE_DATA_FLOW": 2,
    "REPORT_RESTORE_RISK": 3,
    "DISABLE_DATA_FLOW": 0,
    "BLOCK_RESTORE": 1,
    "DELETE_RECORD": 2,
    "REDACT_RECORD": 3,
    "ANONYMIZE_RECORD": 4,
    "VERIFY_RECORD_ABSENT": 0,
    "VERIFY_RECORD_PRESENT": 1,
    "VERIFY_RECORD_REDACTED": 2,
    "VERIFY_RECORD_ANONYMIZED": 3,
    "VERIFY_DATA_FLOW_DISABLED": 4,
    "VERIFY_RESTORE_BLOCKED": 5,
}


def _ordered_steps(steps: list[Step]) -> tuple[Step, ...]:
    return tuple(sorted(
        steps,
        key=lambda step: (
            {"FINDING": 0, "REMEDIATION": 1, "VERIFICATION": 2}[step.phase],
            _OPERATION_ORDER[step.operation],
            step.system_id,
            step.resource_id,
        ),
    ))


def _build_prediction(request: Mapping[str, str], timeline: CaseTimeline, dataset: Dataset) -> CasePrediction:
    assessments = assess_timeline(timeline, rules_from_rows(dataset.deletion_rules))
    violations = [assessment for assessment in assessments if not assessment.compliant]
    case_id = request["case_id"]

    if violations:
        findings = [step for assessment in violations if (step := _step_from_assessment(assessment, "FINDING"))]
        remediations = [step for assessment in violations if (step := _step_from_assessment(assessment, "REMEDIATION"))]
        verification_by_resource: dict[tuple[str, str, str], Step] = {}
        for assessment in assessments:
            step = _step_from_assessment(assessment, "VERIFICATION")
            if step:
                key = (step.system_id, step.resource_id, step.operation)
                prior = verification_by_resource.get(key)
                if prior is None or (not prior.evidence_id and step.evidence_id):
                    verification_by_resource[key] = step
        steps = _ordered_steps(findings + remediations + list(verification_by_resource.values()))
        return CasePrediction(case_id=case_id, deletion_status="INCOMPLETE", steps=steps)

    verification_by_resource = {}
    for assessment in assessments:
        if not assessment.compliant:
            continue
        step = _step_from_assessment(assessment, "VERIFICATION")
        if not step:
            continue
        key = (step.system_id, step.resource_id, step.operation)
        prior = verification_by_resource.get(key)
        if prior is None or (not prior.evidence_id and step.evidence_id):
            verification_by_resource[key] = step

    if not verification_by_resource:
        # Without evidence-backed checks, the workflow claim is insufficient
        # to certify completion. No unsupported finding is fabricated.
        return CasePrediction(case_id=case_id, deletion_status="INCOMPLETE", steps=())
    return CasePrediction(
        case_id=case_id,
        deletion_status="COMPLETE",
        steps=_ordered_steps(list(verification_by_resource.values())),
    )


def investigate_case(
    request: Mapping[str, str],
    dataset: Dataset,
    corpus: EvidenceCorpus,
) -> CasePrediction:
    """Investigate one request using only information available by audit_at."""
    case_id = request["case_id"]
    if not request_authorizes_deletion(request.get("request_text", "")):
        return CasePrediction(case_id=case_id, deletion_status="NOT_APPLICABLE", steps=())

    subject = _resolve_case_subject(request, dataset)
    timeline = build_case_timeline(
        corpus,
        subject,
        request.get("audit_at", ""),
        dataset.system_activity,
    )
    return _build_prediction(request, timeline, dataset)

